    std::vector<Robot> fleet{
        {"Five Sides", 87, false},
        {"Spare", 12, true},
        {"Red-Bot", 45, false},
        {"Blue-Bot", 8, true},
    };

    for (Robot& r : fleet) {
        if (r.charging) {
            r.battery = std::min(100, r.battery + 20);
        }
    }

    int total = std::accumulate(fleet.begin(), fleet.end(), 0,
                                [](int sum, const Robot& r) { return sum + r.battery; });
